"""Generate a source-only ERD from ORM metadata; no settings or database connections."""

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "backend"))
from app.models import Base


def main():
    lines = [
        "# Learning database ERD",
        "",
        (
            "Generated by scripts/write_erd.py from SQLAlchemy metadata. Migration alignment "
            "is tested with Alembic against isolated PostgreSQL."
        ),
        "",
        "```mermaid",
        "erDiagram",
    ]
    for table in Base.metadata.sorted_tables:
        for key in sorted(table.foreign_keys, key=lambda key: key.parent.name):
            lines.append(f"  {key.column.table.name} ||--o{{ {table.name} : {key.parent.name}")
    for table in Base.metadata.sorted_tables:
        lines.append(f"  {table.name} {{")
        for column in table.columns:
            keys = []
            if column.primary_key:
                keys.append("PK")
            if column.foreign_keys:
                keys.append("FK")
            if column.unique:
                keys.append("UK")
            suffix = " " + ",".join(keys) if keys else ""
            lines.append(f"    {type(column.type).__name__.lower()} {column.name}{suffix}")
        lines.append("  }")
    lines += [
        "```",
        "",
        (
            "Supabase-only migration constraints additionally reference "
            "auth.users(id) for user_progress, review_items and quiz_attempts. That external "
            "schema is not owned by this application's ORM metadata."
        ),
        "",
    ]
    (ROOT / "docs/ERD.md").write_text("\n".join(lines), encoding="utf-8")
    print(f"ERD generated for {len(Base.metadata.tables)} application tables; no DB connection")


if __name__ == "__main__":
    main()
